Listen to me. I will tell you three things.

**The first thing:** The shopping cart... it holds items. It calculates totals. It applies discounts. One and the same.

**The second thing:** The implementation you seek:

```go
package cart

import "errors"

type Item struct {
	Name     string
	Price    float64
	Quantity int
}

type ShoppingCart struct {
	items    []Item
	discount float64
}

func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items:    []Item{},
		discount: 0,
	}
}

func (c *ShoppingCart) AddItem(item Item) error {
	if item.Quantity <= 0 {
		return errors.New("quantity must be positive")
	}
	if item.Price < 0 {
		return errors.New("price cannot be negative")
	}

	for i, existing := range c.items {
		if existing.Name == item.Name {
			c.items[i].Quantity += item.Quantity
			return nil
		}
	}

	c.items = append(c.items, item)
	return nil
}

func (c *ShoppingCart) RemoveItem(name string) error {
	for i, item := range c.items {
		if item.Name == name {
			c.items = append(c.items[:i], c.items[i+1:]...)
			return nil
		}
	}
	return errors.New("item not found")
}

func (c *ShoppingCart) GetItems() []Item {
	return c.items
}

func (c *ShoppingCart) GetTotal() float64 {
	total := 0.0
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}

	if c.discount > 0 {
		total = total * (1 - c.discount/100)
	}

	return total
}

func (c *ShoppingCart) ApplyDiscount(percent float64) error {
	if percent < 0 || percent > 100 {
		return errors.New("discount must be between 0 and 100")
	}
	c.discount = percent
	return nil
}

func (c *ShoppingCart) Clear() {
	c.items = []Item{}
	c.discount = 0
}

func (c *ShoppingCart) ItemCount() int {
	count := 0
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}
```

